package khoa.tools.client.feature.ruler;
import com.mojang.brigadier.builder.LiteralArgumentBuilder; import net.fabricmc.fabric.api.client.command.v2.*; import net.fabricmc.fabric.api.client.event.lifecycle.v1.ClientTickEvents; import net.fabricmc.fabric.api.client.rendering.v1.level.LevelRenderEvents; import net.minecraft.client.Minecraft; import net.minecraft.commands.CommandBuildContext; import net.minecraft.gizmos.*; import net.minecraft.network.chat.Component; import net.minecraft.util.ARGB; import net.minecraft.world.phys.*; import khoa.tools.client.feature.KhoaFeature;
public final class RulerFeature implements KhoaFeature { private static boolean on,wasAttack,wasUse; private static Vec3 first,second;
 public String id(){return "ruler";} public String displayName(){return "Ruler";} public String description(){return "Left click sets point 1; right click sets point 2. Block break and placement are blocked while active.";} public boolean isActive(){return on;}
 public static boolean consumesAttack(Minecraft mc){return on&&mc.hitResult instanceof BlockHitResult h&&h.getType()==HitResult.Type.BLOCK;} public static boolean consumesUse(Minecraft mc){return consumesAttack(mc);}
 public void activate(Minecraft mc){on=!on;wasAttack=wasUse=false;KhoaFeature.say(mc,"Ruler: "+(on?"on - left=point 1, right=point 2":"off"));}
 public void onInit(){ClientTickEvents.END_CLIENT_TICK.register(mc->{if(!on||mc.player==null)return;boolean a=mc.options.keyAttack.isDown(),u=mc.options.keyUse.isDown();boolean click=(a&&!wasAttack)||(u&&!wasUse);if(click&&mc.hitResult instanceof BlockHitResult h&&h.getType()==HitResult.Type.BLOCK){Vec3 p=h.getBlockPos().getCenter();if(a&&!wasAttack){first=p;KhoaFeature.say(mc,"Ruler: point 1 updated");}else{second=p;KhoaFeature.say(mc,"Ruler: point 2 updated");}if(first!=null&&second!=null)KhoaFeature.say(mc,String.format("Ruler: %.3f blocks",first.distanceTo(second)));}wasAttack=a;wasUse=u;});LevelRenderEvents.END_EXTRACTION.register(c->{if(first!=null)Gizmos.point(first,ARGB.color(255,80,220,255),8).setAlwaysOnTop();if(first!=null&&second!=null){Gizmos.point(second,ARGB.color(255,80,220,255),8).setAlwaysOnTop();Gizmos.line(first,second,ARGB.color(255,80,220,255),3).setAlwaysOnTop();Gizmos.billboardText(String.format("%.3f blocks",first.distanceTo(second)),first.lerp(second,.5),TextGizmo.Style.forColorAndCentered(ARGB.color(255,80,220,255)).withScale(.5F)).setAlwaysOnTop();}});}
 public void registerCommands(LiteralArgumentBuilder<FabricClientCommandSource> root,CommandBuildContext c){root.then(ClientCommands.literal(id()).executes(x->{activate(x.getSource().getClient());return 1;}));}
}
